function rxExplain(pattern, flags){
  pattern = String(pattern==null?'':pattern);
  flags = String(flags==null?'':flags);
  var tokens=[], i=0, depth=0;
  function err(msg){ return {valid:false, error:msg, parts:tokens, summary:''}; }
  while(i<pattern.length){
    var c=pattern[i];
    if(c==='\\'){
      if(i+1>=pattern.length) return err('末尾悬空的转义符 \\');
      var e=pattern[i+1]; i+=2;
      var map={'d':'数字 [0-9]','D':'非数字','w':'单词字符 [A-Za-z0-9_]','W':'非单词字符','s':'空白字符','S':'非空白字符','b':'单词边界','B':'非单词边界','n':'换行符','t':'制表符','r':'回车符'};
      if(map.hasOwnProperty(e)) tokens.push({t:'\\'+e, desc:map[e]});
      else tokens.push({t:'\\'+e, desc:'字面字符「'+e+'」'});
      continue;
    }
    if(c==='['){
      var j=pattern.indexOf(']', i+1);
      if(j<0) return err('字符类缺少闭合 ]');
      var cls=pattern.slice(i, j+1), neg=pattern[i+1]==='^';
      tokens.push({t:cls, desc:(neg?'排除字符集 ':'字符集 ')+(neg?cls.slice(2,-1):cls.slice(1,-1))});
      i=j+1; continue;
    }
    if(c==='('){
      if(pattern[i+1]==='?' && pattern[i+2]===':'){ tokens.push({t:'(?:', desc:'非捕获分组（不记录）'}); i+=3; depth++; continue; }
      tokens.push({t:'(', desc:'捕获分组 #'+(depth+1)}); i++; depth++; continue;
    }
    if(c===')'){ tokens.push({t:')', desc:'分组结束'}); i++; depth=Math.max(0,depth-1); continue; }
    if(c==='^'){ tokens.push({t:'^', desc:'字符串开头'}); i++; continue; }
    if(c==='$'){ tokens.push({t:'$', desc:'字符串结尾'}); i++; continue; }
    if(c==='.'){ tokens.push({t:'.', desc:'任意字符（除换行）'}); i++; continue; }
    if(c==='|'){ tokens.push({t:'|', desc:'或（二选一）'}); i++; continue; }
    if(c==='*'||c==='+'||c==='?'){
      var q={'*':'零次或多次','+':'一次或多次','?':'零次或一次'}[c];
      tokens.push({t:c, desc:q}); i++; continue;
    }
    if(c==='{'){
      var mm=pattern.slice(i).match(/^\{(\d+)(,(\d*))?\}/);
      if(!mm){ tokens.push({t:'{', desc:'字面「{」'}); i++; continue; }
      var desc = mm[2]===undefined ? '精确 '+mm[1]+' 次' : (mm[3]==='' ? mm[1]+' 次或更多' : mm[1]+'-'+mm[3]+' 次');
      tokens.push({t:mm[0], desc:desc}); i+=mm[0].length; continue;
    }
    tokens.push({t:c, desc:'字面字符「'+c+'」'}); i++;
  }
  if(depth>0) return err('分组括号未闭合');
  var summary = tokens.length + ' 个片段' + (flags?('，标志 '+flags):'') + (flags.indexOf('i')>=0?'（忽略大小写）':'') + (flags.indexOf('g')>=0?'（全局匹配）':'') + (flags.indexOf('m')>=0?'（多行）':'');
  return {valid:true, error:null, parts:tokens, summary:summary};
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { rxExplain:rxExplain };
}
if (typeof window !== 'undefined') {
  window.RegexExplainForgePure = { rxExplain:rxExplain };
}
